calls.statement:
WITH d AS (
  SELECT receipt_id, line_no, COUNT(*) n FROM fact_sales_line GROUP BY 1,2 HAVING COUNT(*)>1
)
SELECT dd.fiscal_year, dd.fiscal_week, COUNT(*) dup_rows, SUM(f.net_amount) amt, MIN(f.sale_date) mn, MAX(f.sale_date) mx, COUNT(DISTINCT f.store_key) stores
FROM fact_sales_line f JOIN d USING (receipt_id, line_no) JOIN dim_date dd ON dd.calendar_date=f.sale_date
GROUP BY 1,2 ORDER BY 1,2;
